 25	static unsigned char convertToDoomKey(unsigned int key)
 26	{
 27	  switch (key)
 28	    {
 29	    case SDLK_RETURN:
 30	      key = KEY_ENTER;
 31	      break;
 32	    case SDLK_ESCAPE:
 33	      key = KEY_ESCAPE;
 34	      break;
 35	    case SDLK_LEFT:
 36	      key = KEY_LEFTARROW;
 37	      break;
 38	    case SDLK_RIGHT:
 39	      key = KEY_RIGHTARROW;
 40	      break;
 41	    case SDLK_UP:
 42	      key = KEY_UPARROW;
 43	      break;
 44	    case SDLK_DOWN:
 45	      key = KEY_DOWNARROW;
 46	      break;
 47	    case SDLK_LCTRL:
 48	    case SDLK_RCTRL:
 49	      key = KEY_FIRE;
 50	      break;
 51	    case SDLK_SPACE:
 52	      key = KEY_USE;
 53	      break;
 54	    case SDLK_LSHIFT:
 55	    case SDLK_RSHIFT:
 56	      key = KEY_RSHIFT;
 57	      break;
 58	    case SDLK_LALT:
 59	    case SDLK_RALT:
 60	      key = KEY_LALT;
 61	      break;
 62	    case SDLK_F2:
 63	      key = KEY_F2;
 64	      break;
 65	    case SDLK_F3:
 66	      key = KEY_F3;
 67	      break;
 68	    case SDLK_F4:
 69	      key = KEY_F4;
 70	      break;
 71	    case SDLK_F5:
 72	      key = KEY_F5;
 73	      break;
 74	    case SDLK_F6:
 75	      key = KEY_F6;
 76	      break;
 77	    case SDLK_F7:
 78	      key = KEY_F7;
 79	      break;
 80	    case SDLK_F8:
 81	      key = KEY_F8;
 82	      break;
 83	    case SDLK_F9:
 84	      key = KEY_F9;
 85	      break;
 86	    case SDLK_F10:
 87	      key = KEY_F10;
 88	      break;
 89	    case SDLK_F11:
 90	      key = KEY_F11;
 91	      break;
 92	    case SDLK_EQUALS:
 93	    case SDLK_PLUS:
 94	      key = KEY_EQUALS;
 95	      break;
 96	    case SDLK_MINUS:
 97	      key = KEY_MINUS;
 98	      break;
 99	    default:
100	      key = tolower(key);
101	      break;
102	    }
103	
104	  return key;
105	}
