107	static void addKeyToQueue(int pressed, unsigned int keyCode)
108	{
109	  unsigned char key = convertToDoomKey(keyCode);
110	
111	  unsigned short keyData = (pressed << 8) | key;
112	
113	  s_KeyQueue[s_KeyQueueWriteIndex] = keyData;
114	  s_KeyQueueWriteIndex++;
115	  s_KeyQueueWriteIndex %= KEYQUEUE_SIZE;
116	}
117	
118	static void handleKeyInput()
119	{
120	  SDL_Event e;
121	  while (SDL_PollEvent(&e))
122	  {
123	    if (e.type == SDL_QUIT)
124	    {
125	      puts("Quit requested");
126	      atexit(SDL_Quit);
127	      exit(1);
128	    }
129	
130	    if (e.type == SDL_KEYDOWN)
131	    {
132	      addKeyToQueue(1, e.key.keysym.sym);
133	    }
134	    else if (e.type == SDL_KEYUP)
135	    {
136	      addKeyToQueue(0, e.key.keysym.sym);
137	    }
138	  }
139	}
