183	int DG_GetKey(int* pressed, unsigned char* doomKey)
184	{
185	  if (s_KeyQueueReadIndex == s_KeyQueueWriteIndex)
186	  {
187	    //key queue is empty
188	    return 0;
189	  }
190	  else
191	  {
192	    unsigned short keyData = s_KeyQueue[s_KeyQueueReadIndex];
193	    s_KeyQueueReadIndex++;
194	    s_KeyQueueReadIndex %= KEYQUEUE_SIZE;
195	
196	    *pressed = keyData >> 8;
