234	// Check for the uninstall strings from the CD versions
235	
236	static void CheckUninstallStrings(void)
237	{
238	    unsigned int i;
239	
240	    for (i=0; i<arrlen(uninstall_values); ++i)
241	    {
242	        char *val;
243	        char *path;
244	        char *unstr;
245	
246	        val = GetRegistryString(&uninstall_values[i]);
247	
248	        if (val == NULL)
249	        {
250	            continue;
251	        }
252	
253	        unstr = strstr(val, UNINSTALLER_STRING);
254	
255	        if (unstr == NULL)
256	        {
257	            free(val);
258	        }
259	        else
260	        {
261	            path = unstr + strlen(UNINSTALLER_STRING);
262	
263	            AddIWADDir(path);
264	        }
265	    }
266	}
